import astropy.units as u
from astropy.coordinates import SkyCoord, GCRS, ICRS
from astropy.time import Time

def icrs_ra_from_gcrs_4(ra_deg: float, dec_deg: float, obstime: Time) -> float:
    coord = SkyCoord(ra=ra_deg * u.deg, dec=dec_deg * u.deg, frame=ICRS(obstime=obstime))
    return float(coord.ra.deg)
